params.query:
DECLARE below_safe STRING DEFAULT (
  SELECT STRING_AGG(FORMAT('%s=%s', t.table_name, IFNULL(o.option_value, 'unset')), ', ' ORDER BY t.table_name)
  FROM `test-project.mock_da2_scan.INFORMATION_SCHEMA.TABLES` t
  LEFT JOIN `test-project.mock_da2_scan.INFORMATION_SCHEMA.TABLE_OPTIONS` o
    ON o.table_name = t.table_name AND o.option_name = 'max_staleness'
  WHERE t.table_name IN ('scan_sv_1_update_history_creates', 'scan_sv_1_update_history_exercises', 'scan_sv_1_scan_verdict_store', 'scan_sv_1_scan_verdict_transaction_view_store', 'scan_sv_1_app_activity_record_store')
    AND (o.option_value IS NULL
      OR CAST(o.option_value AS INTERVAL) < MAKE_INTERVAL(second => 14400))
);
IF below_safe IS NOT NULL THEN
  RAISE USING MESSAGE = CONCAT('splice-legacy-bq-max-staleness-below-safe cluster=mock: max_staleness below 14400s on ', below_safe);
END IF;
